using System;
using System.Collections.Generic;

class Aluno
{
    public string Nome { get; }
    private List<int> notas = new List<int>();

    public Aluno(string nome)
    {
        Nome = nome;
    }

    public void AdicionarNota(int nota)
    {
        notas.Add(nota);
    }

    public double Media()
    {
        int soma = 0;
        foreach (int nota in notas) soma += nota;
        return (double)soma / notas.Count;
    }
}

class Program
{
    static void Main()
    {
        int n = int.Parse(Console.ReadLine());
        if (n == 0)
        {
            Console.WriteLine("Nenhum aluno");
            return;
        }

        var ordem = new List<Aluno>();
        var porNome = new Dictionary<string, Aluno>();
        for (int i = 0; i < n; i++)
        {
            string[] partes = Console.ReadLine().Split(' ', StringSplitOptions.RemoveEmptyEntries);
            string nome = partes[0];
            int nota = int.Parse(partes[1]);
            if (!porNome.TryGetValue(nome, out Aluno aluno))
            {
                aluno = new Aluno(nome);
                porNome[nome] = aluno;
                ordem.Add(aluno);
            }
            aluno.AdicionarNota(nota);
        }

        Aluno melhor = ordem[0];
        foreach (Aluno a in ordem)
        {
            Console.WriteLine($"{a.Nome}: {a.Media():F2}");
            if (a.Media() > melhor.Media()) melhor = a;
        }
        Console.WriteLine($"Melhor: {melhor.Nome}");
    }
}

