            "+" => checked(a + b),
            "-" => checked(a - b),
            "*" => checked(a * b),
            "/" => checked(a / b),
            _ => throw new ArgumentException($"operador desconhecido '{op}'")
        };
    }

    static void Main()
    {
        int n = int.Parse(Console.ReadLine());
        int sucessos = 0, erros = 0;
        for (int i = 1; i <= n; i++)
        {
            string[] p = (Console.ReadLine() ?? "").Split(' ', StringSplitOptions.RemoveEmptyEntries);
            try
            {
                int a = int.Parse(p[0]);
                int b = int.Parse(p[2]);
                int r = Calcular(a, p[1], b);
                Console.WriteLine($"{a} {p[1]} {b} = {r}");
                sucessos++;
            }
            catch (DivideByZeroException)
            {
                Console.WriteLine($"Linha {i}: divisão por zero");
                erros++;
            }
            catch (OverflowException)
            {
                Console.WriteLine($"Linha {i}: valor fora do limite do int");
                erros++;
            }
            catch (FormatException)
            {
                Console.WriteLine($"Linha {i}: número inválido");
                erros++;
            }
            catch (ArgumentException e)
            {
                Console.WriteLine($"Linha {i}: {e.Message}");
                erros++;
            }
        }
        Console.WriteLine($"Sucessos: {sucessos}, erros: {erros}");
    }
}

