lessons.solution:
using System.Globalization;

interface IForma
{
    string Nome { get; }
    double Area();
    double Perimetro();
}

class Retangulo : IForma
{
    private readonly double largura, altura;
    public Retangulo(double largura, double altura) { this.largura = largura; this.altura = altura; }
    public string Nome => "Retângulo";
    public double Area() => largura * altura;
    public double Perimetro() => 2 * (largura + altura);
}

class Circulo : IForma
{
    private readonly double raio;
    public Circulo(double raio) { this.raio = raio; }
    public string Nome => "Círculo";
    public double Area() => Math.PI * raio * raio;
    public double Perimetro() => 2 * Math.PI * raio;
}

class Triangulo : IForma
{
    private readonly double a, b, c;
    public Triangulo(double a, double b, double c) { this.a = a; this.b = b; this.c = c; }
    public string Nome => "Triângulo";
    public double Perimetro() => a + b + c;
    public double Area()
    {
        double s = Perimetro() / 2;
        return Math.Sqrt(s * (s - a) * (s - b) * (s - c));
    }
}

class Program
{
    static double Num(string s) => double.Parse(s, CultureInfo.InvariantCulture);

    static IForma Criar(string[] p)
    {
        return p[0] switch
        {
            "retangulo" => new Retangulo(Num(p[1]), Num(p[2])),
            "circulo" => new Circulo(Num(p[1])),
            _ => new Triangulo(Num(p[1]), Num(p[2]), Num(p[3]))
        };
    }

    static void Main()
    {
        int n = int.Parse(Console.ReadLine());
        var formas = new List<IForma>();
        for (int i = 0; i < n; i++)
        {
            formas.Add(Criar(Console.ReadLine().Split(' ', StringSplitOptions.RemoveEmptyEntries)));
        }
        double total = 0;
        IForma maior = formas[0];
        foreach (IForma f in formas)
        {
            Console.WriteLine($"{f.Nome}: área {f.Area():F2}, perímetro {f.Perimetro():F2}");
            total += f.Area();
            if (f.Area() > maior.Area()) maior = f;
        }
        Console.WriteLine($"Área total: {total:F2}");
        Console.WriteLine($"Maior: {maior.Nome}");
    }
}

