lessons.solution:
class Pilha<T>
{
    private readonly List<T> itens = new List<T>();

    public int Count => itens.Count;

    public void Push(T item)
    {
        itens.Add(item);
    }

    public T Pop()
    {
        if (itens.Count == 0) throw new InvalidOperationException("pilha vazia");
        T topo = itens[itens.Count - 1];
        itens.RemoveAt(itens.Count - 1);
        return topo;
    }
}

class Program
{
    static T Maior<T>(IEnumerable<T> itens) where T : IComparable<T>
    {
        bool primeiro = true;
        T maior = default!;
        foreach (T x in itens)
        {
            if (primeiro || x.CompareTo(maior) > 0)
            {
                maior = x;
                primeiro = false;
            }
        }
        if (primeiro) throw new InvalidOperationException("sequência vazia");
        return maior;
    }

    static List<T> Inverter<T>(IEnumerable<T> itens)
    {
        var pilha = new Pilha<T>();
        foreach (T x in itens) pilha.Push(x);
        var resultado = new List<T>();
        while (pilha.Count > 0) resultado.Add(pilha.Pop());
        return resultado;
    }

    static void Main()
    {
        int[] numeros = Console.ReadLine().Split(' ', StringSplitOptions.RemoveEmptyEntries).Select(int.Parse).ToArray();
        string[] palavras = Console.ReadLine().Split(' ', StringSplitOptions.RemoveEmptyEntries);
        Console.WriteLine($"Maior número: {Maior(numeros)}");
        Console.WriteLine($"Maior palavra: {Maior(palavras)}");
        Console.WriteLine($"Números invertidos: {string.Join(" ", Inverter(numeros))}");
        Console.WriteLine($"Palavras invertidas: {string.Join(" ", Inverter(palavras))}");
    }
}

