    {
        string comandos = (Console.ReadLine() ?? "").Trim();
        var atual = new Ponto(0, 0);
        var visitados = new HashSet<Ponto> { atual };
        // Escreva aqui: mova o robô e procure a primeira repetição
        Console.WriteLine($"Final: {atual}");
