lessons.solution:
record Ponto(int X, int Y)
{
    public Ponto Mover(char direcao)
    {
        return direcao switch
        {
            'N' => this with { Y = Y + 1 },
            'S' => this with { Y = Y - 1 },
            'L' => this with { X = X + 1 },
            'O' => this with { X = X - 1 },
            _ => this
        };
    }

    public int Manhattan() => Math.Abs(X) + Math.Abs(Y);
}

class Program
{
    static void Main()
    {
        string comandos = (Console.ReadLine() ?? "").Trim();
        var atual = new Ponto(0, 0);
        var visitados = new HashSet<Ponto> { atual };
        Ponto? repetido = null;
        int passo = 0;
        for (int i = 0; i < comandos.Length; i++)
        {
            atual = atual.Mover(comandos[i]);
            if (!visitados.Add(atual) && repetido == null)
            {
                repetido = atual;
                passo = i + 1;
            }
        }
        Console.WriteLine($"Final: {atual}");
        Console.WriteLine($"Distância de Manhattan: {atual.Manhattan()}");
        Console.WriteLine($"Pontos distintos: {visitados.Count}");
        Console.WriteLine(repetido == null ? "Nenhuma repetição" : $"Primeira repetição: {repetido} no passo {passo}");
    }
}

