class Program
{
    static void Main()
    {
        int[] moedas = Console.ReadLine().Split(' ', StringSplitOptions.RemoveEmptyEntries).Select(int.Parse).ToArray();
        int valor = int.Parse(Console.ReadLine());

        int[] minimo = new int[valor + 1];
        Array.Fill(minimo, int.MaxValue);
        minimo[0] = 0;
        for (int v = 1; v <= valor; v++)
        {
            foreach (int m in moedas)
            {
                if (m <= v && minimo[v - m] != int.MaxValue && minimo[v - m] + 1 < minimo[v])
                {
                    minimo[v] = minimo[v - m] + 1;
                }
            }
        }

        long[] formas = new long[valor + 1];
        formas[0] = 1;
        foreach (int m in moedas)
        {
            for (int v = m; v <= valor; v++)
            {
                formas[v] += formas[v - m];
            }
        }

        if (minimo[valor] == int.MaxValue)
        {
            Console.WriteLine("Impossível");
        }
        else
        {
            Console.WriteLine($"Mínimo de moedas: {minimo[valor]}");
            var usadas = new List<int>();
            int[] decrescentes = moedas.OrderByDescending(m => m).ToArray();
            int resto = valor;
            while (resto > 0)
            {
                int escolhida = decrescentes.First(m => m <= resto && minimo[resto - m] == minimo[resto] - 1);
                usadas.Add(escolhida);
                resto -= escolhida;
            }
            Console.WriteLine(usadas.Count == 0 ? "Moedas: nenhuma" : $"Moedas: {string.Join(" ", usadas)}");
        }
        Console.WriteLine($"Formas: {formas[valor]}");
    }
}

