class Program
{
    static bool EhPrimo(long n)
    {
        if (n < 2) return false;
        for (long d = 2; d * d <= n; d++)
        {
            if (n % d == 0) return false;
        }
        return true;
    }

    static IEnumerable<long> Primos()
    {
        for (long n = 2; ; n++)
        {
            if (EhPrimo(n)) yield return n;
        }
    }

    static IEnumerable<long> Collatz(long n)
    {
        while (true)
        {
            yield return n;
            if (n == 1) yield break;
            n = n % 2 == 0 ? n / 2 : 3 * n + 1;
        }
    }

    static void Main()
    {
        string[] p = Console.ReadLine().Split(' ', StringSplitOptions.RemoveEmptyEntries);
        int n = int.Parse(p[0]);
        long k = long.Parse(p[1]);
        Console.WriteLine($"Primeiros {n} primos: {string.Join(" ", Primos().Take(n))}");
        Console.WriteLine($"Primeiro primo maior que {k}: {Primos().First(x => x > k)}");
        Console.WriteLine($"Soma dos primos menores que {k}: {Primos().TakeWhile(x => x < k).Sum()}");
        List<long> seq = Collatz(k).ToList();
        Console.WriteLine($"Collatz({k}): {string.Join(" ", seq)}");
        Console.WriteLine($"Passos: {seq.Count - 1}");
        Console.WriteLine($"Pico: {seq.Max()}");
    }
}

