class Program
{
    static void Main()
    {
        string[] p = Console.ReadLine().Split(' ', StringSplitOptions.RemoveEmptyEntries);
        int v = int.Parse(p[0]), e = int.Parse(p[1]);
        var adj = new List<(int destino, int peso)>[v];
        for (int i = 0; i < v; i++) adj[i] = new List<(int destino, int peso)>();
        for (int i = 0; i < e; i++)
        {
            string[] a = Console.ReadLine().Split(' ', StringSplitOptions.RemoveEmptyEntries);
            adj[int.Parse(a[0])].Add((int.Parse(a[1]), int.Parse(a[2])));
        }
        int origem = int.Parse(Console.ReadLine());

        long[] dist = new long[v];
        Array.Fill(dist, long.MaxValue);
        dist[origem] = 0;
        var fila = new PriorityQueue<int, long>();
        fila.Enqueue(origem, 0);
        while (fila.TryDequeue(out int u, out long d))
        {
            if (d > dist[u]) continue;
            foreach (var (w, peso) in adj[u])
            {
                long nova = d + peso;
                if (nova < dist[w])
                {
                    dist[w] = nova;
                    fila.Enqueue(w, nova);
                }
            }
        }

        int maisDistante = -1;
        for (int i = 0; i < v; i++)
        {
            Console.WriteLine(dist[i] == long.MaxValue ? $"{i}: inalcançável" : $"{i}: {dist[i]}");
            if (dist[i] != long.MaxValue && (maisDistante == -1 || dist[i] > dist[maisDistante])) maisDistante = i;
        }
        Console.WriteLine($"Mais distante: {maisDistante} ({dist[maisDistante]})");
    }
}
